{
  "interviewee": {
    "name": "עודד הראל",
    "role": "Sales Director Israel",
    "company": "Automat-it",
    "company_type": "AWS Premier Partner",
    "communication_preference": "verbal (stated preference — prefers speaking over writing)"
  },
  "role": {
    "title": "Sales Director Israel",
    "core_responsibility": "Manage sales pipeline, client relationships, and forecasts. Primary buyer personas: CTOs, DevOps leads, procurement managers.",
    "manages": "Sales team",
    "sales_cycle": "Long — cloud migration and AWS infrastructure deals",
    "customer_segments": "Enterprise and strategic accounts"
  },
  "routines": {
    "morning_sequence": [
      "Outlook email — identify urgent client requests",
      "Salesforce pipeline review — check activity dates, close dates, next steps",
      "Identify stuck deals (no movement 2-3+ weeks)"
    ],
    "midday": [
      "Client meetings: 2-3 per day (CTOs, DevOps, procurement)",
      "Research calls — understanding client pain",
      "Proposals and pricing discussions"
    ],
    "evening": [
      "Reports, forecasts, follow-ups",
      "Catch-up on deferred items"
    ],
    "stuck_deal_process": [
      "1. Review Salesforce conversation history",
      "2. Direct outreach (email or call) — ask what is blocking",
      "3. Validate remaining concerns with targeted questions",
      "4. Create tailored content (case studies, materials for specific objections)",
      "5. Schedule follow-up meeting — sometimes with additional stakeholders",
      "6. Present enhanced value proposition",
      "7. Active post-meeting tracking — thank-you email, reminders, follow-up monitoring"
    ],
    "biggest_time_sinks": [
      "Forecast management and sales data analysis (drains energy)",
      "Writing proposals",
      "Meeting preparation"
    ]
  },
  "systems": {
    "crm": {
      "name": "Salesforce",
      "type": "commercial",
      "usage": "Pipeline management — activity tracking, deal stages, close dates, next steps, conversation history",
      "signal_logic": {
        "active_deal": "Recent activity + defined next step + realistic close date",
        "stuck_deal": "No movement 2+ weeks OR close date passed twice without closing OR no defined next step"
      },
      "integrations": ["Outlook (email sync and calendar)"]
    },
    "email": {
      "platform": "Outlook",
      "type": "commercial",
      "usage": "All client communication, inbound inquiries, prospecting follow-up",
      "integration": "Synced with Salesforce"
    },
    "video": {
      "primary": "Zoom",
      "secondary": "Microsoft Teams",
      "usage": "Client meetings, demos, complex presentations",
      "notes": "Zoom strongly preferred by both Oded and clients"
    },
    "prospecting": {
      "platform": "LinkedIn",
      "type": "commercial",
      "usage": "Identifying potential clients, maintaining professional connections, reaching key decision-makers"
    },
    "forecasting": {
      "platform": "Unspecified — multiple tools referenced",
      "usage": "Sales forecast management, performance measurement, win/loss analysis",
      "notes": "This is an area of pain — Oded avoids and finds draining"
    },
    "task_management": {
      "platform": "Trello or Asana (mentioned, not confirmed as primary tool)",
      "usage": "Task tracking, deal follow-up, project management"
    }
  },
  "volume": {
    "active_deals_pipeline": "10-15 concurrent",
    "meetings_per_day": "2-3",
    "client_segments": "Enterprise / strategic accounts (AWS migrations, cloud infrastructure)"
  },
  "skills_and_judgment": {
    "decides_alone": [
      "Daily client interaction tactics",
      "Response strategy to client questions and objections",
      "When and how to re-engage a stuck deal",
      "Meeting preparation approach and content"
    ],
    "always_escalates": [
      "Pricing changes",
      "Portfolio or product scope decisions",
      "Strategic partnership decisions",
      "Any decision that impacts other team members"
    ],
    "domain_expertise": "Cloud migration sales (AWS), enterprise B2B sales cycles, multi-stakeholder deals (technical + procurement buyers)",
    "natural_strength": "Reading the room — knowing when to stop pitching and start listening"
  },
  "professional_dna": {
    "in_zone": {
      "description": "Client listening + real-time pivot from pitch to problem-solving",
      "specific_example": {
        "client": "אינטליקום",
        "context": "Cloud migration deal — arrived with presentation",
        "trigger": "Tech team asked specific questions about capacity, security, and maintenance",
        "action": "Stopped presenting, started listening. Shared relevant case studies instead of continuing pitch.",
        "result": "Trust established, deal advanced to next stage"
      }
    },
    "drains_energy": [
      "Forecast management and sales data analysis",
      "Deep data review and report filtering",
      "Routine manual administrative updates"
    ],
    "energizes": [
      "Client conversations and real-time problem-solving",
      "Complex deal navigation",
      "Building client relationships"
    ]
  },
  "ai_attitude": {
    "temperament": "skeptical_but_open",
    "behavioral_pattern": "Ends most answers with 'how can AI help here?' — signals genuine curiosity beneath stated skepticism",
    "noted_fears": null,
    "ai_literacy": "high — asks precise, targeted questions about AI capabilities",
    "engagement_key": "Show concrete, measurable ROI. Start with one specific problem (pipeline alerts). Do not oversell."
  },
  "dream_agent": {
    "priority_1": {
      "label": "Pipeline monitoring + stuck-deal alerts",
      "system": "Salesforce",
      "description": "Monitor deals for inactivity, overdue close dates, missing next steps — alert proactively"
    },
    "priority_2": {
      "label": "Pre-meeting intelligence briefing",
      "system": "Salesforce + Outlook",
      "description": "Before each client meeting: summarize past conversations, open items, topics raised, recommended talking points"
    },
    "priority_3": {
      "label": "Cross-system insights",
      "systems": ["Outlook", "LinkedIn", "Salesforce"],
      "description": "Unified view connecting communication, social signals, and deal status"
    }
  }
}

